STORY = [('kawada', '売ってる物がバラバラなんですね。随分落ちぶれたようで。', "You're selling quite a random assortment of things. You seem to have fallen pretty far.", [(365, '売ってる物がバラバラなんですね'), (366, '随分 落ちぶれたようで')], ''), ('muranishi', 'そう見えるならそうなんだろうな。それでも生きてる、間違えちゃいない。', "If that's how it looks, I suppose so. Even so, I'm alive—I haven't gone wrong.", [(367, 'そう見えるなら そうなんだろうな'), (370, 'それでも生きてる 間違えちゃいない')], ''), ('kawada', '巻き込まれた人間はどうなるんです？今回は許さない。', "What about the people dragged down with you? This time, I won't forgive you.", [(371, '巻き込まれた人間は どうなるんです'), (379, '今回は許さない')], ''), ('kawada', 'トシが古谷を殺しました。古谷の事務所にたった一人で乗り込んで。', "Toshi killed Furuya—he stormed into Furuya's office all by himself.", [(380, 'トシが古谷を殺しました'), (381, '古谷の事務所に'), (382, '乗り込んで')], 'spelled numeral in kanji'), ('kawada', 'あいつがどういう覚悟だったか分かるよな？あんたを優先させたんだよ！', "You understand what kind of resolve that took, don't you? He put your life ahead of his own!", [(383, 'あいつが どういう覚悟だったか 分かるよな'), (384, 'あんたを優先させたんだよ')], ''), ('kawada', '誰もがあんたの魅力にあらがえない、自分が死ぬことを選んでまで。', 'Nobody can resist your magnetism—even to the point of choosing his own death.', [(386, '誰もが あんたの魅力に あらがえない'), (387, '自分が死ぬことを選んでまで')], ''), ('muranishi', '待ってくれ。', 'Wait—please stop...', [(388, '待ってくれ')], ''), ('kawada', 'あいつはね、あなたのことをずーっと受け入れ続けたたった一人の男ですよ。', 'He was the one and only man who kept accepting you unconditionally all the way through.', [(391, 'あいつはね'), (392, 'あなたのことを ずーっと'), (393, 'ずーっと受け入れ続けた')], 'spelled numeral in kanji'), ('kawada', 'あいつからあんたのことを拒んだことないだろ。', 'He never once turned his back on you, did he?', [(395, 'あいつから あんたのことを 拒んだことないだろ')], ''), ('toshi', 'おっさんが好きなようにやりゃいいんだよ。ビッグマネーつかんで成り上がるんだよ！', "Do things your own way, boss! Let's grab big money and rise to the top!", [(398, 'おっさんが好きなように やりゃいいんだよ'), (403, 'ビッグマネーつかんでよ 成り上がるんだよ')], 'tightened interjection'), ('kawada', '全部つないでくれたのは結局あいつなんですよ。だからせめて村西さんらしくしてください。', 'In the end, he was the one who held everything together. So at the very least, live like yourself, Mr. Muranishi.', [(410, '全部つないでくれたのは'), (411, '結局 あいつなんですよ'), (412, 'だから せめて'), (413, '村西さんらしく してください')], ''), ('kawada', 'あいつが好きだったのは、監督としてのあなたなんです。', 'What Toshi loved was who you were as a director.', [(414, 'あいつが好きだったのは'), (415, '監督としての あなたなんです')], '')]
